package dev.nexflow.inventory; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/inventory") public class InventoryController {private final InventoryService service;public InventoryController(InventoryService s){service=s;}@GetMapping("/movements")public List<InventoryDtos.MovementView> movements(){return service.recent();}@PostMapping("/adjust")@ResponseStatus(HttpStatus.NO_CONTENT)public void adjust(@Valid @RequestBody InventoryDtos.AdjustmentRequest r, Authentication a){service.adjust(r,a.getName());}}
